using System;
using CargoWise.Blazor.SessionBroker.Authentication;
using CargoWise.Blazor.SessionBroker.Helpers;
using Enterprise.Integration;
using Moq;

namespace CargoWise.Blazor.SessionBroker.Test
{
	public static class ConfigWithOIDCSettingsHelper
	{
		public static IAuthenticationConfigAccessor WithRegistryAccessor(this IOIDCConfig oicdConfig)
		{
			var registryAccessorMock = new Mock<IAuthenticationConfigAccessor>();
			registryAccessorMock
				.Setup(m => m.GetOIDCConfig())
				.Returns(oicdConfig);

			registryAccessorMock
				.Setup(m => m.GetDomainHint())
				.Returns("Azure");

			return registryAccessorMock.Object;
		}

		public static Mock<IDatabaseAccessor> DatabaseAccessorWithOIDCMock()
		{
			var dbAccessorMock = new Mock<IDatabaseAccessor>();
			dbAccessorMock.Setup(databaseAccessor =>
				databaseAccessor.ExecuteScalar<object>(
					It.IsAny<string>(),
					System.Data.CommandType.StoredProcedure,
					It.IsAny<(string ParameterName, object Value)[]>()))
				.Returns(OIDCBinaryValue());
			return dbAccessorMock;
		}

		public static Mock<IDatabaseAccessor> DatabaseAccessorWithDomainHintMock(bool isDefault = true)
		{
			var dbAccessorMock = new Mock<IDatabaseAccessor>();
			dbAccessorMock.Setup(databaseAccessor =>
				databaseAccessor.ExecuteScalar<object>(
					It.IsAny<string>(),
					System.Data.CommandType.StoredProcedure,
					It.IsAny<(string ParameterName, object Value)[]>()))
				.Returns(DomainHintBinaryValue(isDefault));
			return dbAccessorMock;
		}

		public static Mock<IDatabaseAccessor> DatabaseAccessorWithDBSchemaVersionMock(string hexString = null)
		{
			var dbAccessorMock = new Mock<IDatabaseAccessor>();
			dbAccessorMock.Setup(databaseAccessor =>
				databaseAccessor.ExecuteScalar<object>(
					It.IsAny<string>(),
					System.Data.CommandType.StoredProcedure,
					It.IsAny<(string ParameterName, object Value)[]>()))
				.Returns(DBSchemaVersionBinaryValue(hexString));
			return dbAccessorMock;
		}

		public static object OIDCBinaryValue()
		{
			var hexString = "";
			return GetByteArrayFromString(hexString);
		}

		public static object DomainHintBinaryValue(bool isDefault)
		{
			var hexString = isDefault ? string.Empty : "0x570043005F00450044004900";
			return ParseHexStringToDBBinaryValue(hexString);
		}

		public static object DBSchemaVersionBinaryValue(string hexString = null)
		{
			return ParseHexStringToDBBinaryValue(hexString);
		}

		static object ParseHexStringToDBBinaryValue(string hexString)
		{
			if (!string.IsNullOrEmpty(hexString))
			{
				return GetByteArrayFromString(hexString);
			}

			return DBNull.Value;
		}

		static byte[] GetByteArrayFromString(string hexString)
		{
			if (hexString.StartsWith("0x", StringComparison.OrdinalIgnoreCase))
			{
				hexString = hexString.Substring(2);
			}

			var byteArray = new byte[hexString.Length / 2];
			for (var i = 0; i < byteArray.Length; i++)
			{
				byteArray[i] = Convert.ToByte(hexString.Substring(i * 2, 2), 16);
			}

			return byteArray;
		}
	}
}
